<?php require_once __DIR__.'/../inc/db.php';session_set_cookie_params(['httponly'=>true,'samesite'=>'Lax','secure'=>!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off']);session_start();$db=db();ensure_payment_col();
